162	                .map(fieldError -> {
163	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
164	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
165	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
166	                        fieldError.getField(),
167	                        defaultMessage,
168	                        rejectedValue);
169	                    return new ValidationMessageDto(message)
170	                        .putAdditionalProperty("field", fieldError.getField())
171	                        .putAdditionalProperty("rejectedValue", rejectedValue)
172	                        .putAdditionalProperty("defaultMessage", defaultMessage);
173	                })
174	                .toList();
175	            List<String> errorFields = bindingResult.getFieldErrors().stream()
176	                .map(FieldError::getField)
177	                .distinct()
178	                .toList();
179	            logger.debug("Validation error at {} {}: {}",
180	                request.getMethod(),
181	                request.getRequestURI(),
182	                bindingResult.getFieldErrors());
183	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
184	            detail.setProperty("errors", errorFields);
185	            return ResponseEntity.status(status).body(detail);
186	        }
187	        return ResponseEntity.status(status).body(detail);
188	    }
189	
190	}
